#include "KS/SRC/ks/wave_perturb_shared.h"

template <int n>
float WavePulsePerturbClass<n>::WorldToPulse(float worldx)
{
    static const float &domain = pulsex[num - 1];
    assert(pulsex[0] == 0);

    float progress;

    switch (WAVE_PerturbStage)
    {
    case WAVE_PerturbStageDo:
        progress = WAVE_PerturbProgress;
        break;
    case WAVE_PerturbStageUndo:
        progress = WAVE_PerturbProgress + 1;
        break;
    default:
        progress = 1;
        break;
    }

    float modx = worldx - offset + (progress - 1) * domain;
    modx = min(max(0.f, modx), domain);

    float profilex = worldx;
    profilex += SPLINE_Evaluate(
        pulsex,
        pulsecoeffs.a,
        pulsecoeffs.b,
        pulsecoeffs.c,
        pulsecoeffs.d,
        num,
        modx);
    profilex -= modx;

    return profilex;
}

template float WavePulsePerturbClass<6>::WorldToPulse(float worldx);
